<script setup lang="ts">
import { onUnmounted, ref, watch } from 'vue';
import PhotoField from './PhotoField.vue';
import { forumEnabled } from '../../shared/features';
const emit = defineEmits<{ (event: 'share'): void }>();
import { api, mediaBlob } from '../api';
import { type Row } from '../../shared/domain';
import { useGallery } from '../../shared/useGallery';
const props = defineProps<{ user: Row | null }>();const { albums, photos, selected, source, error, busy, manage, staff, detail, save, photo, togglePhoto } = useGallery(() => props.user, api);
const pendingPhotos = ref<Row[]>([]), photosPending = ref(false), success = ref('');
watch(() => selected.value?.id, () => { pendingPhotos.value = [];photosPending.value = false;success.value = ''; });
const editing = ref(false), form = ref<Row>({}), uploading = ref(false), preview = ref(''), previewCaption = ref('');
function edit(row?: Row) { form.value = row ? { ...row } : { title: '', description: '', location: '', date: new Date().toISOString().slice(0,10), status: 'draft' };editing.value = true; }
async function submit() { if (await save(form.value)) editing.value = false; }
async function publishPhotos() {
  if (uploading.value || photosPending.value || !pendingPhotos.value.length) return;
  const albumId = selected.value?.id;uploading.value = true;success.value = '';let count = 0;
  try { for (const row of [...pendingPhotos.value]) {
    if (selected.value?.id !== albumId) break;
    if (!await photo(row.id, row.name.replace(/\.[^.]+$/, ''), albumId)) break;
    count++;pendingPhotos.value = pendingPhotos.value.filter(p => p.id !== row.id);
  } if (selected.value?.id === albumId && count) success.value = `已添加 ${count} 张照片`;
  } finally { uploading.value = false; }
}
let alive = true;
watch(() => props.user?.id, () => { closePreview();editing.value = false; });
async function show(row: Row) { const userId = props.user?.id, albumId = selected.value?.id;try { const blob = await mediaBlob(row.mediaId);if (!alive || props.user?.id !== userId || selected.value?.id !== albumId) return;if (preview.value) URL.revokeObjectURL(preview.value);preview.value = URL.createObjectURL(blob);previewCaption.value = row.caption; } catch(e) { error.value = (e as Error).message; } }
function closePreview() { URL.revokeObjectURL(preview.value);preview.value = ''; }
onUnmounted(() => { alive = false;closePreview(); });
</script>
<template><section class="gallery"><div v-if="!selected && !editing" class="module-heading"><div><p class="eyebrow">OUR SHARED MOMENTS</p><h1>相聚的日子，值得珍藏。</h1><p>把乡音、笑脸与每一次相助，留在家里的相册。</p></div><div v-if="staff" class="button-row"><button class="outline" @click="manage = !manage">{{ manage ? '返回公开相册' : '管理相册' }}</button><button class="primary" @click="edit()">新建相册</button></div></div><p v-if="error" class="form-error" role="alert">{{ error }}</p>
<form v-if="editing" class="panel album-form" @submit.prevent="submit"><h3>{{ form.id ? '编辑相册' : '新建活动相册' }}</h3><label>相册名称<input v-model="form.title" required minlength="2" maxlength="80"></label><div class="form-grid"><label>活动日期<input v-model="form.date" type="date" required></label><label>地点<input v-model="form.location" maxlength="150"></label></div><label>相册介绍<textarea v-model="form.description" maxlength="2000"></textarea></label><label>状态<select v-model="form.status"><option value="draft">草稿</option><option value="published">公开展示</option></select></label><p class="form-tip">请确认照片具备展示授权，尊重参与者的隐私和撤图请求。</p><div class="button-row"><button class="primary" :disabled="busy">保存相册</button><button type="button" class="outline" @click="editing = false">取消</button></div></form>
<template v-else-if="selected"><button class="text-button" :disabled="uploading || photosPending" @click="selected = null">← 所有相册</button><div class="module-heading"><div><h1>{{ selected.title }}</h1><p>{{ selected.date }} · {{ selected.location }}</p><p>{{ selected.description }}</p></div><div v-if="staff" class="button-row"><button class="outline" :disabled="uploading || photosPending" @click="edit(selected)">编辑相册</button></div></div><section v-if="staff" class="album-uploader"><PhotoField :key="selected.id" v-model="pendingPhotos" :user-id="user?.id" scope="album" :disabled="uploading" @busy="photosPending = $event"/><button class="primary" :disabled="uploading || photosPending || !pendingPhotos.length" @click="publishPhotos">{{ uploading ? '正在添加…' : '添加到相册（' + pendingPhotos.length + '张）' }}</button><p v-if="success" class="status-note" role="status">{{ success }}</p></section><div v-if="!photos.length" class="empty">相册还没有照片，等待记录下第一份美好。</div><div class="photo-wall"><article v-for="row in photos" :key="row.id"><button @click="show(row)"><img v-if="row.status === 'published' && selected.status === 'published'" :src="'/api/media/' + row.mediaId" :alt="row.caption" loading="lazy"><div v-else class="private-photo">点击预览未公开照片</div></button><div><p>{{ row.caption }}</p><button v-if="staff" class="text-button" :disabled="busy" @click="togglePhoto(row)">{{ row.status === 'published' ? '隐藏照片' : '恢复展示' }}</button></div></article></div></template>
<template v-else><section v-if="forumEnabled && !staff" class="panel"><h3>你的镜头，也有家乡的故事</h3><p class="prose">活动相册由管理团队整理，你也可以到论坛分享自己的照片。</p><button class="outline" @click="emit('share')">去论坛分享照片 →</button></section><a class="source-album" :href="source.url" target="_blank" rel="noopener noreferrer"><span class="source-mark">忆</span><div><small>我们的活动原相册</small><h3>{{ source.title }}</h3><p>打开摄影相册，重温相聚的时刻</p></div><span>前往查看 ↗</span></a><div v-if="!albums.length" class="empty">活动影像正在整理中，可先查看上方原相册。</div><div class="album-grid"><button v-for="album in albums" :key="album.id" class="album-card" @click="detail(album)"><img v-if="album.cover && album.status === 'published'" :src="'/api/media/' + album.cover" :alt="album.title" loading="lazy"><div v-else class="album-placeholder">乡情 · 留影</div><div><small>{{ album.date }} · {{ album.count }} 张照片</small><h3>{{ album.title }}</h3><p>{{ album.location || album.description }}</p><span v-if="manage">{{ album.status === 'published' ? '已公开' : '草稿' }}</span></div></button></div></template><div v-if="preview" class="gallery-viewer" @click.self="closePreview"><button @click="closePreview">关闭 ×</button><img :src="preview" :alt="previewCaption"><p>{{ previewCaption }}</p></div></section></template>
<style scoped>.album-uploader{margin-bottom:28px}.album-uploader>.primary{margin-bottom:16px}.module-heading{display:flex;justify-content:space-between;gap:25px;align-items:center;margin:16px 0 28px}.module-heading :is(h1,h2){font-size:28px;margin:12px 0}.module-heading p{color:#7c8888;line-height:1.9;font-size:13px}.source-album{display:flex;align-items:center;gap:28px;background:#233f54;color:#fff9ed;border-radius:24px;padding:30px;margin-bottom:30px}.source-mark{font:52px 'KaiTi',serif;background:#e0cb9d;color:#405563;border-radius:50%;width:85px;height:85px;display:grid;place-items:center;flex-shrink:0}.source-album>div{flex:1}.source-album h3{font-size:23px;margin:8px 0}.source-album p,.source-album small{color:#c3d0cc;font-size:12px}.source-album>span:last-child{font-size:12px}.album-grid,.photo-wall{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.album-card{border:1px solid #e8e0d1;border-radius:20px;background:#fffefa;overflow:hidden;text-align:left}.album-card img,.album-placeholder{width:100%;height:205px;object-fit:cover}.album-placeholder{background:#e9e2d1;display:grid;place-items:center;color:#8e7851;font:24px 'KaiTi',serif}.album-card>div:last-child{padding:22px}.album-card h3{font-size:19px;margin:10px 0}.album-card small,.album-card p,.album-card span{color:#938870;font-size:12px}.photo-wall article{background:#fffefa;border-radius:18px;overflow:hidden;border:1px solid #e8e1d2}.photo-wall article>button{display:block;width:100%}.photo-wall img{width:100%;height:240px;object-fit:cover;display:block}.photo-wall article>div{padding:16px;font-size:13px}.private-photo{height:180px;background:#eee8db;display:grid;place-items:center;color:#988669}.upload-label{cursor:pointer;position:relative;font-size:13px;display:inline-block}.upload-label input{position:absolute;opacity:0;width:1px;height:1px}.gallery-viewer{position:fixed;inset:0;background:#172b39f5;z-index:220;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:50px 20px;color:white}.gallery-viewer>button{position:absolute;right:25px;top:20px}.gallery-viewer img{max-width:95%;max-height:80vh;object-fit:contain}.gallery-viewer p{margin-top:18px}.album-form{max-width:700px}@media(max-width:900px){.album-grid,.photo-wall{grid-template-columns:repeat(2,minmax(0,1fr))}.module-heading{align-items:flex-start;flex-direction:column}}@media(max-width:520px){.album-grid{grid-template-columns:1fr}.photo-wall{gap:10px}.photo-wall img{height:160px}.source-album{padding:22px;gap:16px}.source-mark{width:60px;height:60px;font-size:32px}.source-album>span:last-child{display:none}.module-heading :is(h1,h2){font-size:23px}}</style>
